types.declaration:
export interface AgentActivityPresentation {
  readonly title: string;
  readonly icon?: AgentActivityPresentationIcon;
  readonly requestPayload?: readonly AgentActivityPresentationField[];
  readonly resultPayload?: readonly AgentActivityPresentationField[];
}

/** Agent 资源展示字段只供 Tool Call 卡片使用，永不进入模型上下文。 */
export interface AgentActivityPresentationField {
  readonly label?: string;
  readonly value: string;
  readonly unit?: string;
}

/** Ask 工具等待 Renderer 回答时投影的单选问题；自定义输入由客户端固定追加。 */
export interface AgentAskInteraction extends AgentInteractionBase {
  readonly type: "ask";
  readonly question: string;
  readonly options: readonly string[];
}

interface AgentInteractionBase {
  readonly id: string;
  readonly invocationId: string;
  readonly toolCallId: string;
  readonly createdAt: string;
}

export type AgentInteractionResponse =
  | {
      readonly interactionId: string;
      readonly type: "ask-option";
      readonly optionIndex: number;
    }
  | {
      readonly interactionId: string;
      readonly type: "ask-custom";
      readonly value: string;
    }
  | {
      readonly interactionId: string;
      readonly type: "tool-confirmation";
      readonly approved: boolean;
    };

export interface AgentInteractionResponseInput {
  readonly invocationId: string;
  readonly response: AgentInteractionResponse;
}

export interface AgentInvocationSnapshot extends AgentInvocationSummary {
  readonly text: string;
  readonly contentBlocks: readonly AgentMessageContentBlock[];
  readonly provider?: AgentProviderResponseDetails;
  readonly usage?: AgentTokenUsage;
  readonly toolCalls: readonly AgentToolCallSnapshot[];
  /** 本次 Invocation 已生成的新 Session 标题，供运行中的客户端立即同步侧栏。 */
  readonly sessionTitle?: string;
  /** 等待 Ask 回答或命令确认时，只在运行期公开的交互请求。 */
  readonly interaction?: AgentPendingInteraction;
  /** 当前 Invocation 最近一次由 todo 工具写入的完整任务清单。 */
  readonly todo?: AgentTodoSnapshot;
}

export interface AgentInvocationSummary {
  readonly id: string;
  readonly sessionId: string;
  readonly state: AgentInvocationState;
  readonly model: AgentModelSelection;
  readonly startedAt: string;
  readonly finishedAt?: string;
  readonly error?: string;
  /** 当前 Invocation 最后一个模型 Step 完成后的上下文 Token。 */
  readonly contextTokens?: number;
}

export type AgentMessageContentBlock =
  | {
      readonly type: "text";
      readonly text: string;
    }
  | {
      readonly type: "reasoning";
      readonly text: string;
      readonly redacted?: boolean;
    }
  | {
      readonly type: "tool-call";
      readonly toolCallId: string;
    };

export interface AgentModelSelection {
  readonly connectionId: string;
  readonly modelId: string;
  /** 当前 Invocation 选择的推理档位；档位名称由模型设置声明。 */
  readonly reasoningLevel?: string;
}

/** 单个模型 Step 的供应商身份与停止原因；不包含认证信息和加密推理签名。 */
export interface AgentProviderResponseDetails {
  readonly api: string;
  readonly provider: string;
  readonly requestedModel: string;
  readonly responseModel?: string;
  readonly responseId?: string;
  readonly stopReason: string;
  readonly errorMessage?: string;
  readonly rawStopReason?: string;
  readonly endTurn?: boolean;
  readonly diagnostics?: readonly JsonObject[];
}

export interface AgentTodoItem {
  readonly content: string;
  readonly status: AgentTodoStatus;
}

/** 当前 Invocation 的完整任务清单；每次 todo 调用都用新快照原子替换。 */
export interface AgentTodoSnapshot {
  readonly items: readonly AgentTodoItem[];
  readonly updatedAt: string;
}

/** 供应商返回的原始用量分类；reasoning 已包含在 output 中。 */
export interface AgentTokenUsage {
  readonly input: number;
  readonly output: number;
  readonly cacheRead: number;
  readonly cacheWrite: number;
  readonly cacheWrite1h?: number;
  readonly reasoning?: number;
  readonly totalTokens: number;
  readonly cost?: AgentTokenUsageCost;
}

export interface AgentTokenUsageCost {
  readonly input: number;
  readonly output: number;
  readonly cacheRead: number;
  readonly cacheWrite: number;
  readonly total: number;
}

/** Agent 调用工具时持久化并投影给客户端的稳定活动记录。 */
export interface AgentToolCallSnapshot {
  readonly id: string;
  readonly invocationId: string;
  readonly toolName: string;
  readonly presentation: AgentActivityPresentation;
  readonly state: AgentToolCallState;
  readonly input: JsonValue;
  readonly output?: JsonValue;
  readonly error?: string;
  readonly startedAt: string;
  /** 工具开始前已经输出的 Assistant 文本长度；使用 JavaScript UTF-16 偏移量。 */
  readonly assistantTextOffset: number;
  readonly finishedAt?: string;
}

/** 高权限工具在真正进入领域 Handler 前等待用户确认。 */
export interface AgentToolConfirmationInteraction extends AgentInteractionBase {
  readonly type: "tool-confirmation";
  readonly toolName: string;
  readonly title: string;
  readonly confirmationLevel: Exclude<AgentToolConfirmationLevel, 0>;
  readonly input: JsonValue;
}

export interface AgentConfiguredModel extends AgentModelSelection {
  readonly name: string;
  readonly settings?: AgentModelSettings;
}

/** revision 对应 models.yml 字节内容；diagnostics 描述未取代最后有效配置的加载故障。 */
export interface AgentModelConfigurationSnapshot {
  readonly revision: string;
  readonly connections: readonly AgentModelConnectionConfig[];
  readonly models: readonly AgentConfiguredModel[];
  readonly providerTypes: readonly AgentProviderTypeDescriptor[];
  readonly diagnostics: readonly string[];
}

/** Renderer 可读取的连接投影不包含凭据正文。 */
export interface AgentModelConnectionConfig {
  readonly id: string;
  readonly displayName?: string;
  readonly providerType: string;
  readonly credentialId?: string;
  readonly credentialConfigured: boolean;
  readonly settings: JsonObject;
  readonly models?: readonly AgentModelConnectionModel[];
  readonly available: boolean;
  readonly diagnostic?: string;
}

export interface AgentModelConnectionModel {
  readonly id: string;
  readonly displayName?: string;
  readonly providerOptions?: JsonObject;
  readonly settings?: AgentModelSettings;
}

export type AgentModelConnectionMutation =
  | {
      readonly op: "set";
      readonly path: readonly string[];
      readonly value: JsonValue;
    }
  | {
      readonly op: "unset";
      readonly path: readonly string[];
    };

export interface AgentModelCost {
  /** 每百万输入 Token 的供应商标价。 */
  readonly input: number;
  /** 每百万输出 Token 的供应商标价。 */
  readonly output: number;
  /** 每百万缓存读取 Token 的供应商标价。 */
  readonly cacheRead: number;
  /** 每百万缓存写入 Token 的供应商标价。 */
  readonly cacheWrite: number;
}

export interface AgentModelSelection {
  readonly connectionId: string;
  readonly modelId: string;
  /** 当前 Invocation 选择的推理档位；档位名称由模型设置声明。 */
  readonly reasoningLevel?: string;
}

/** 每个模型独立保存的能力元数据；推理档位使用供应商实际接收的值。 */
export interface AgentModelSettings {
  readonly maximumContextTokens: number;
  readonly maximumOutputTokens?: number;
  readonly reasoningLevels: readonly string[];
  readonly inputModalities?: readonly ("text" | "image")[];
  readonly api?: string;
  readonly cost?: AgentModelCost;
}

/** Provider Type 的只读元数据；工厂和凭据只存在于 Core Host。 */
export interface AgentProviderTypeDescriptor {
  readonly id: string;
  readonly displayName: string;
  readonly settingsSchema: JsonObject;
  readonly catalog?: readonly AgentModelConnectionModel[];
  readonly supportsModelDiscovery: boolean;
}

export interface AgentActivityPresentation {
  readonly title: string;
  readonly icon?: AgentActivityPresentationIcon;
  readonly requestPayload?: readonly AgentActivityPresentationField[];
  readonly resultPayload?: readonly AgentActivityPresentationField[];
}

/** Agent 资源展示字段只供 Tool Call 卡片使用，永不进入模型上下文。 */
export interface AgentActivityPresentationField {
  readonly label?: string;
  readonly value: string;
  readonly unit?: string;
}

export interface AgentConfiguredModel extends AgentModelSelection {
  readonly name: string;
  readonly settings?: AgentModelSettings;
}

export interface AgentInvocationReference {
  readonly sessionId: string;
  readonly invocationId: string;
}

export type AgentMessageContentBlock =
  | {
      readonly type: "text";
      readonly text: string;
    }
  | {
      readonly type: "reasoning";
      readonly text: string;
      readonly redacted?: boolean;
    }
  | {
      readonly type: "tool-call";
      readonly toolCallId: string;
    };

export interface AgentMessageSnapshot {
  readonly id: string;
  readonly invocationId: string;
  readonly role: "user" | "assistant";
  /** 纯文本投影，供搜索、标题与第一版调用方继续使用。 */
  readonly content: string;
  readonly contentBlocks: readonly AgentMessageContentBlock[];
  readonly provider?: AgentProviderResponseDetails;
  readonly usage?: AgentTokenUsage;
  readonly timestamp: string;
}

export interface AgentModelCost {
  /** 每百万输入 Token 的供应商标价。 */
  readonly input: number;
  /** 每百万输出 Token 的供应商标价。 */
  readonly output: number;
  /** 每百万缓存读取 Token 的供应商标价。 */
  readonly cacheRead: number;
  /** 每百万缓存写入 Token 的供应商标价。 */
  readonly cacheWrite: number;
}

export interface AgentModelSelection {
  readonly connectionId: string;
  readonly modelId: string;
  /** 当前 Invocation 选择的推理档位；档位名称由模型设置声明。 */
  readonly reasoningLevel?: string;
}

/** 每个模型独立保存的能力元数据；推理档位使用供应商实际接收的值。 */
export interface AgentModelSettings {
  readonly maximumContextTokens: number;
  readonly maximumOutputTokens?: number;
  readonly reasoningLevels: readonly string[];
  readonly inputModalities?: readonly ("text" | "image")[];
  readonly api?: string;
  readonly cost?: AgentModelCost;
}

/** 单个模型 Step 的供应商身份与停止原因；不包含认证信息和加密推理签名。 */
export interface AgentProviderResponseDetails {
  readonly api: string;
  readonly provider: string;
  readonly requestedModel: string;
  readonly responseModel?: string;
  readonly responseId?: string;
  readonly stopReason: string;
  readonly errorMessage?: string;
  readonly rawStopReason?: string;
  readonly endTurn?: boolean;
  readonly diagnostics?: readonly JsonObject[];
}

export interface AgentSessionSnapshot extends AgentSessionSummary {
  readonly messages: readonly AgentMessageSnapshot[];
  readonly toolCalls: readonly AgentToolCallSnapshot[];
  /** Session 最近一次成功 TODO 更新；供响应结束后继续展示任务进度。 */
  readonly todo?: AgentTodoSnapshot;
  /** 最近一次成功取得供应商用量的 Invocation 所占上下文 Token。 */
  readonly contextTokens?: number;
}

export interface AgentSessionSummary {
  readonly id: string;
  readonly title: string;
  readonly model: AgentModelSelection;
  readonly createdAt: string;
  readonly updatedAt: string;
}

export interface AgentTodoItem {
  readonly content: string;
  readonly status: AgentTodoStatus;
}

/** 当前 Invocation 的完整任务清单；每次 todo 调用都用新快照原子替换。 */
export interface AgentTodoSnapshot {
  readonly items: readonly AgentTodoItem[];
  readonly updatedAt: string;
}

/** 供应商返回的原始用量分类；reasoning 已包含在 output 中。 */
export interface AgentTokenUsage {
  readonly input: number;
  readonly output: number;
  readonly cacheRead: number;
  readonly cacheWrite: number;
  readonly cacheWrite1h?: number;
  readonly reasoning?: number;
  readonly totalTokens: number;
  readonly cost?: AgentTokenUsageCost;
}

export interface AgentTokenUsageCost {
  readonly input: number;
  readonly output: number;
  readonly cacheRead: number;
  readonly cacheWrite: number;
  readonly total: number;
}

/** Agent 调用工具时持久化并投影给客户端的稳定活动记录。 */
export interface AgentToolCallSnapshot {
  readonly id: string;
  readonly invocationId: string;
  readonly toolName: string;
  readonly presentation: AgentActivityPresentation;
  readonly state: AgentToolCallState;
  readonly input: JsonValue;
  readonly output?: JsonValue;
  readonly error?: string;
  readonly startedAt: string;
  /** 工具开始前已经输出的 Assistant 文本长度；使用 JavaScript UTF-16 偏移量。 */
  readonly assistantTextOffset: number;
  readonly finishedAt?: string;
}

export interface AgentUserMessage {
  readonly text: string;
}

/** 可跨 Host/Client 边界传输的 Agent 设置快照。 */
export interface AgentSettingsSnapshot {
  readonly automaticConversationSummary: boolean;
}

/** 公共下载任务快照；metadata 由创建任务的业务组件解释。 */
export interface DownloadTaskSnapshot {
  readonly id: string;
  readonly url: string;
  readonly destinationPath: string;
  readonly state: DownloadTaskState;
  readonly downloadedBytes: number;
  readonly totalBytes: number;
  /** 实际使用的连接数；探测完成前为 0。 */
  readonly connections: number;
  readonly progress: number;
  readonly createdAt: string;
  readonly finishedAt?: string;
  readonly error?: string;
  readonly metadata?: JsonValue;
}

/** 顶栏文件下载条使用的公共任务投影，不向 Renderer 暴露远端 URL 与业务 metadata。 */
export interface FileDownloadTaskSnapshot {
  id: string;
  destinationPath: string;
  state: FileDownloadTaskState;
  downloadedBytes: number;
  totalBytes: number;
  connections: number;
  progress: number;
  createdAt: string;
  finishedAt?: string;
  error?: string;
}

/**
 * 公共下载组件接收完整目标文件路径，而不是某一种业务目录。
 *
 * 服务端、模组、插件和自定义文件组件负责决定自己的目录结构与最终文件名。
 */
export interface StartDownloadRequest {
  readonly url: string;
  readonly destinationPath: string;
  readonly expectedBytes?: number;
  readonly sha256?: string;
  readonly sha1?: string;
  readonly sha512?: string;
  /** 期望的并发连接数；远端不支持 Range 时自动退回单连接。 */
  readonly connections?: number;
  readonly headers?: Readonly<Record<string, string>>;
  readonly metadata?: JsonValue;
}

/** 自动发现的 Java 安装；路径已经由 Host 解析为规范化绝对路径。 */
export interface JavaInstallationSnapshot {
  id: string;
  path: string;
  javaHome: string;
  version: string;
  majorVersion: number;
  vendor: string;
  architecture: string;
  is64Bit: boolean;
  source: JavaInstallationSource;
  /** 禁用项继续展示，但不会参与服务器启动时的 Java 选择。 */
  disabled: boolean;
}

/** 第三方包内单个 Entry 的只读运行状态。 */
export interface PluginManagementEntrySnapshot {
  readonly id: string;
  readonly runtimeId: string;
  readonly runtime: PluginRuntime;
  readonly enabled: boolean;
  readonly state: PluginManagementEntryState;
  readonly uses: Readonly<Record<string, readonly string[]>>;
  readonly error?: string;
}

/** 当前 Host 实际采用的第三方包；开发覆盖与已安装版本按插件 ID 合并。 */
export interface PluginManagementSnapshot {
  readonly id: string;
  readonly version: string;
  readonly publisher: string;
  readonly source: Exclude<PluginSourceKind, "builtin">;
  readonly trust: Exclude<PluginTrustLevel, "builtin" | "official">;
  readonly digest: string;
  readonly installedAt: string;
  readonly enabled: boolean;
  readonly entries: readonly PluginManagementEntrySnapshot[];
}

/** 插件发布包声明的 SeaShard 与 Client Protocol 兼容范围。 */
export interface PluginMarketCompatibility {
  readonly seaShard: string;
  readonly clientProtocol?: string;
}

/** Registry CI 从发布包 Manifest 中提取的单个 Entry 摘要。 */
export interface PluginMarketEntry {
  readonly id: string;
  readonly runtime: PluginRuntime;
  readonly uses: Readonly<Record<string, readonly string[]>>;
  readonly hostProfiles?: readonly HostProfile[];
  readonly targets?: readonly ClientTarget[];
  readonly os?: readonly OperatingSystem[];
  readonly arch?: readonly CpuArchitecture[];
}

/** 官方注册目录中的完整插件记录；列表与详情共享同一份已校验数据。 */
export interface PluginMarketPlugin {
  readonly id: string;
  readonly name: string;
  readonly summary: string;
  readonly owners: readonly string[];
  readonly source: PluginMarketSource;
  readonly license: string;
  readonly releases: readonly PluginMarketRelease[];
}

/**
 * Registry CI 校验后的不可变发布记录。
 *
 * archiveSha256 固定下载归档字节，packageDigest 固定 SeaShard 解包后的包内容身份。
 */
export interface PluginMarketRelease {
  readonly version: string;
  readonly tag: string;
  readonly releaseUrl: string;
  readonly downloadUrl: string;
  readonly archiveSha256: string;
  readonly packageDigest: string;
  readonly publisher: string;
  readonly compatibility: PluginMarketCompatibility;
  readonly entries: readonly PluginMarketEntry[];
  readonly fileCount: number;
  readonly unpackedSize: number;
  readonly yanked: boolean;
}

export interface PluginMarketSearchRequest {
  readonly query: string;
  readonly page: number;
  readonly pageSize: number;
  /** 忽略 Host 内存缓存，重新下载官方 Latest Release Catalog。 */
  readonly refresh?: boolean;
}

export interface PluginMarketSearchResult {
  readonly totalCount: number;
  readonly page: number;
  readonly pageSize: number;
  readonly fetchedAt: string;
  readonly plugins: readonly PluginMarketPlugin[];
}

/** 注册目录中可公开展示的插件源码位置。 */
export interface PluginMarketSource {
  readonly type: "github";
  readonly repository: string;
  readonly url: string;
}

/** 插件市场用于判断安装、更新和开发覆盖状态的最小投影。 */
export interface PluginMarketInstallationSnapshot {
  readonly id: string;
  readonly version: string;
  readonly digest: string;
  readonly source: "installed" | "development";
  readonly enabled: boolean;
}

/** 一键安装只传 Registry 主键；下载地址和摘要始终由 Host 从受信 Catalog 重新解析。 */
export interface PluginMarketInstallRequest {
  readonly pluginId: string;
  readonly version: string;
  readonly acknowledgeFullMachineAccess: true;
}

/** 面向客户端的单个插件运行视图。 */
export type ComponentSnapshot = {
  id: string;
  displayName: string;
  phase: RuntimePhase;
  error?: string;
};

/** 可跨插件 Service 与 IPC 传输的稳定运行态读取模型。 */
export type RuntimeSnapshot = {
  protocolVersion: 1;
  host: "electron";
  state: "active" | "degraded" | "stopping";
  startedAt: string;
  components: ComponentSnapshot[];
};

/** 单个实例当前可编辑配置的目录；其他配置只在实际发现文件时显示。 */
export interface ServerConfigurationCatalog {
  instanceId: string;
  serverType?: string;
  /** 实际配置根目录；Quilt 等核心可能位于实例根目录的子目录。 */
  configurationRootPath: string;
  pluginSupported: boolean;
  serverFiles: readonly ServerConfigurationFile[];
  otherFiles: readonly ServerConfigurationFile[];
  plugins: readonly ServerPluginConfigurationGroup[];
}

/** revision 是原始文件字节的 SHA-256，用于拒绝覆盖服务器或外部编辑器的新修改。 */
export interface ServerConfigurationDocument extends ServerConfigurationFile {
  instanceId: string;
  content: string;
  revision: string;
  encoding: ServerConfigurationTextEncoding;
  modifiedAt: string;
}

/** Renderer 可选择的配置文件只使用实例内相对路径，不暴露宿主绝对路径。 */
export interface ServerConfigurationFile {
  path: string;
  name: string;
  kind: ServerConfigurationFileKind;
  scope: ServerConfigurationFileScope;
  pluginName?: string;
}

export interface ServerConfigurationWriteRequest {
  instanceId: string;
  path: string;
  content: string;
  expectedRevision: string;
}

export interface ServerPluginConfigurationGroup {
  name: string;
  files: readonly ServerConfigurationFile[];
}

/** 顶栏文件下载条使用的公共任务投影，不向 Renderer 暴露远端 URL 与业务 metadata。 */
export interface FileDownloadTaskSnapshot {
  id: string;
  destinationPath: string;
  state: FileDownloadTaskState;
  downloadedBytes: number;
  totalBytes: number;
  connections: number;
  progress: number;
  createdAt: string;
  finishedAt?: string;
  error?: string;
}

/** Renderer 可安全读取的服务端核心产物；下载地址只由宿主目录服务提供。 */
export interface ServerCoreArtifact {
  source: "cnb";
  serverType: string;
  gameVersion: string;
  fileName: string;
  url: string;
  sha256: string;
}

/** 顶栏和下载页共享的服务器核心任务投影。 */
export interface ServerCoreDownloadTaskSnapshot extends FileDownloadTaskSnapshot {
  artifact: ServerCoreArtifact;
}

/** Renderer 可安全读取的服务端核心类型；图标地址只指向 Host 本地缓存协议。 */
export interface ServerCoreType {
  id: string;
  iconUrl?: string;
}

/** Host 侧下载请求；目录由 Client 平台选择，产物身份仍由核心目录验证。 */
export interface StartServerCoreDownloadRequest {
  serverType: string;
  gameVersion: string;
  destinationDirectory: string;
  artifactFileName: string;
  destinationFileName: string;
  connections: number;
}

/** Host 侧创建托管实例时补入设置组件保存的下载并发数。 */
export interface CreateManagedServerInstanceRequest extends ServerCoreManagedDownloadRequest {
  connections: number;
}

/** 顶栏文件下载条使用的公共任务投影，不向 Renderer 暴露远端 URL 与业务 metadata。 */
export interface FileDownloadTaskSnapshot {
  id: string;
  destinationPath: string;
  state: FileDownloadTaskState;
  downloadedBytes: number;
  totalBytes: number;
  connections: number;
  progress: number;
  createdAt: string;
  finishedAt?: string;
  error?: string;
}

/** Renderer 可安全读取的服务端核心产物；下载地址只由宿主目录服务提供。 */
export interface ServerCoreArtifact {
  source: "cnb";
  serverType: string;
  gameVersion: string;
  fileName: string;
  url: string;
  sha256: string;
}

/** 顶栏和下载页共享的服务器核心任务投影。 */
export interface ServerCoreDownloadTaskSnapshot extends FileDownloadTaskSnapshot {
  artifact: ServerCoreArtifact;
}

/** 托管下载立即返回任务与预留实例 ID，下载完成后可精确跳转到新实例。 */
export interface ServerCoreManagedDownloadResult {
  instanceId: string;
  task: ServerCoreDownloadTaskSnapshot;
}

/** “另存为”只提交目录服务可验证的产物身份，不允许 Renderer 传入任意 URL。 */
export interface ServerCoreSaveAsRequest {
  serverType: string;
  gameVersion: string;
  artifactFileName: string;
  destinationFileName: string;
}

/** 一个已安装 MOD 的稳定投影；relativePath 是实例根目录下的 POSIX 相对路径。 */
export interface ServerInstalledModSnapshot {
  instanceId: string;
  relativePath: string;
  fileName: string;
  name: string;
  version?: string;
  /** 从 MOD 清单读取的简短介绍。 */
  description?: string;
  /** MOD JAR 内部图标的数据地址。 */
  iconDataUrl?: string;
  /** 文件首次落盘时间；手动复制的 MOD 使用文件系统创建时间。 */
  addedAt: string;
  disabled: boolean;
  resourceSource?: ServerResourceSourceMetadata;
}

/** Renderer 只读取已登记实例及其世界存档，不接触宿主文件系统。 */
export interface ServerInstanceContentCounts {
  mods: number;
  plugins: number;
}

/** 服务器事实与 SeaShard 私有 JSON 合并后的稳定 Client 投影。 */
export interface ServerInstanceSnapshot {
  id: string;
  name: string;
  rootPath: string;
  coreJarPath: string;
  iconPath?: string;
  /** 世界下载外层目录的完整名称；例如 worlds-abc123。 */
  worldStorageDirectoryName?: string;
  /** 世界备份外层目录的完整名称；例如 backups-def456。 */
  backupDirectoryName?: string;
  storageMode: ServerInstanceStorageMode;
  source: ServerInstanceSource;
  /** 核心对应的标准 Mod 加载器；纯插件端、代理端和原版核心为 null。 */
  modLoader: ServerModLoader | null;
  serverType?: string;
  gameVersion?: string;
  coreArtifactFileName?: string;
  artifactSha256?: string;
  createdAt: string;
  updatedAt: string;
  iconUrl?: string;
  lastStartedAt?: string;
  /** 已完成运行会话的累计时长；当前会话由 Client 根据 startedAt 实时叠加。 */
  totalRuntimeMs?: number;
  /** 保存后整体覆盖全局启动默认值；缺省表示继续继承全局设置。 */
  startupSettings?: ServerInstanceStartupSettings;
  /** 本地资源到来源展示信息的可选索引；不参与资源归属和版本判断。 */
  resourceSources?: ServerResourceSourceIndex;
}

/** 单个服务器实例持久化的完整启动参数；存在时整体覆盖全局启动默认值。 */
export interface ServerInstanceStartupSettings {
  minimumMemoryMiB: number;
  maximumMemoryMiB: number;
  serverPort: number;
  autoAcceptEula: boolean;
  jvmArguments: string;
}

/** 实例 seashard.json 中按对应资源存储根目录的相对路径保存资源来源索引。 */
export interface ServerResourceSourceIndex {
  mods?: Readonly<Record<string, ServerResourceSourceMetadata>>;
  datapacks?: Readonly<Record<string, ServerResourceSourceMetadata>>;
  worlds?: Readonly<Record<string, ServerResourceSourceMetadata>>;
}

/** 已安装资源的来源标识；未知来源只保留展示信息，不自动生成来源跳转。 */
export interface ServerResourceSourceMetadata {
  source: ServerResourceSource;
  id: string;
  /** 来源发布版本的显示标签，例如 Modrinth 的 version_number。 */
  version?: string;
  iconUrl?: string;
}

/** Host 写入资源来源索引时使用的单条记录。 */
export interface ServerResourceSourceRecord extends ServerResourceSourceMetadata {
  resourceType: ServerResourceSourceType;
  relativePath: string;
}

/** 一个世界备份的稳定投影；路径仅返回文件名，不暴露宿主绝对路径。 */
export interface ServerWorldBackupSnapshot {
  instanceId: string;
  worldId: string;
  worldDirectoryName: string;
  fileName: string;
  createdAt: string;
  sizeBytes: number;
}

/** 一个世界数据包的稳定投影；路径仅返回世界数据包目录中的文件名。 */
export interface ServerWorldDatapackSnapshot {
  instanceId: string;
  worldId: string;
  resourceSource?: ServerResourceSourceMetadata;
  fileName: string;
  kind: ServerWorldDatapackKind;
  disabled: boolean;
  /** 从 pack.mcmeta 读取的简短介绍。 */
  description?: string;
  /** 数据包内部 pack.png 的数据地址。 */
  iconDataUrl?: string;
  updatedAt: string;
}

export interface ServerWorldDimensionGroup {
  id: string;
  name: string;
  current: boolean;
  saves: readonly ServerWorldSave[];
}

/** 一个可切换的世界目录；split 模式下同一组的多个维度共享 groupId。 */
export interface ServerWorldSave {
  id: string;
  groupId: string;
  name: string;
  dimension: ServerWorldDimension;
  current: boolean;
  createdAt?: string;
  resourceSource?: ServerResourceSourceMetadata;
  updatedAt?: string;
  iconDataUrl?: string;
}

/** Host 扫描实例目录后发布的存档稳定投影，不向 Renderer 暴露绝对路径。 */
export interface ServerWorldStorageSnapshot {
  instanceId: string;
  mode: ServerWorldStorageMode;
  currentId?: string;
  saves: readonly ServerWorldSave[];
  dimensions: readonly ServerWorldDimensionGroup[];
}

/** 多来源资源完成校验并发布后的稳定结果。 */
export interface ServerModDownloadResult {
  source: ServerModSource;
  resourceType: ServerModDownloadableResourceType;
  projectId: string;
  versionId: string;
  fileName: string;
  destination: "instance" | "directory";
  instanceId?: string;
  downloadedBytes: number;
}

export interface ServerModFilterOption {
  id: string;
  label: string;
}

/** 单个服务端资源来源的筛选元数据；来源暂时不可用时保留可验证的提示。 */
export interface ServerModFilters {
  sources: readonly ServerModFilterOption[];
  tags: readonly ServerModFilterOption[];
  versions: readonly ServerModFilterOption[];
  loaders: readonly ServerModFilterOption[];
  unavailableReason?: string;
}

/** Renderer 只提交来源、资源类型、项目身份和已登记实例 ID；数据包还要提交已选择的存档 ID。 */
export interface ServerModInstallRequest {
  source: ServerModSource;
  resourceType: "mod" | "datapack" | "world";
  projectId: string;
  versionId: string;
  instanceId: string;
  /** 仅数据包安装使用；Host 会再次确认它属于该实例且确实存在。 */
  worldId?: string;
}

/** 多来源 Mod 搜索结果的最小安全投影；图标仅允许来自受信任的上游 CDN。 */
export interface ServerModProject {
  resourceType: ServerModrinthResourceType;
  source: ServerModSource;
  id: string;
  slug: string;
  title: string;
  iconUrl?: string;
  description: string;
  author: string;
  downloads: number;
  follows: number;
  dateModified: string;
  environment: readonly ServerModEnvironment[];
  categories: readonly string[];
  versions: readonly string[];
}

/** 多来源项目长简介及其全部公开版本。 */
export interface ServerModProjectDetails {
  resourceType: ServerModrinthResourceType;
  source: ServerModSource;
  projectId: string;
  project: ServerModProject;
  body: string;
  versions: readonly ServerModVersion[];
}

/** “另存为”同样只提交来源、资源类型和项目身份，目标目录由 Desktop 系统对话框选择。 */
export interface ServerModSaveAsRequest {
  source: ServerModSource;
  resourceType: ServerModDownloadableResourceType;
  projectId: string;
  versionId: string;
}

/** Client 只能提交声明式筛选条件，不能传入任意上游 URL 或 Facet 表达式。 */
export interface ServerModSearchRequest {
  resourceType: ServerModrinthResourceType;
  source: ServerModSource;
  query: string;
  tag: string;
  index: ServerModSearchIndex;
  gameVersion: string;
  loader: string;
  offset: number;
  limit: number;
}

export interface ServerModSearchResult {
  items: readonly ServerModProject[];
  offset: number;
  limit: number;
  total: number;
  unavailableReason?: string;
}

export interface ServerModSourceSaveRequest extends ServerModSaveAsRequest {
  readonly destinationDirectory: string;
  readonly connections: number;
}

/** 详情页中的单个可下载版本；Host 只投影列表展示所需字段。 */
export interface ServerModVersion {
  id: string;
  gameVersions: readonly string[];
  loaders: readonly string[];
  fileName: string;
  downloads: number;
  datePublished: string;
}

/** 进程输出按实例递增编号，Renderer 可用编号补拉事件订阅前后的缺口。 */
export interface ServerConsoleLine {
  sequence: number;
  instanceId: string;
  stream: ServerConsoleStream;
  text: string;
  timestamp: string;
}

/** 单个服务器实例持久化的完整启动参数；存在时整体覆盖全局启动默认值。 */
export interface ServerInstanceStartupSettings {
  minimumMemoryMiB: number;
  maximumMemoryMiB: number;
  serverPort: number;
  autoAcceptEula: boolean;
  jvmArguments: string;
}

/** 启动组件根据当前 Java 选择和核心策略生成的等价命令行。 */
export interface ServerLaunchCommandPreview {
  instanceId: string;
  command: string;
}

/** 单个服务器进程的可序列化状态；不暴露 ChildProcess 或宿主句柄。 */
export interface ServerRuntimeSnapshot {
  instanceId: string;
  state: ServerProcessState;
  pid?: number;
  startedAt?: string;
  stoppedAt?: string;
  exitCode?: number;
  error?: string;
}

/** 可持久化并跨 Host/Client 边界传输的服务器设置快照。 */
export interface ServerSettingsSnapshot extends ServerStartupDefaultsUpdate {
  resourceDownloadDirectory: string;
  defaultDownloadConnections: number;
}

/** 一次性提交相互依赖的启动默认值，避免最小内存与最大内存出现中间非法状态。 */
export interface ServerStartupDefaultsUpdate {
  defaultMinimumMemoryMiB: number;
  defaultMaximumMemoryMiB: number;
  defaultServerPort: number;
  autoAcceptEula: boolean;
  defaultJvmArguments: string;
}
